# Run from the package root after a rebuild, 02, 29, 39, 46, 66 and 67 (the numbers they save):  Rscript data-raw/qa/68_known_issues_core.R
# Writes the sections of data-raw/known_issues.md that describe the data and the SPC exposure, each between <!-- name:start --> and <!-- name:end -->: intro, loss, coordinates, spc-line, identifiers, ratings, dependence and settings.
# Every number is computed here from the data in data/, the provenance files or the saved results of the QA scripts named in the text. The text of the settings table gives each constant of the package with its definition, value, reason and effect.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x); need <- function(f) { if (!file.exists(qa_out(f))) stop("Missing data-raw/qa/out/", f, ": run the script that writes it first.", call. = FALSE); readRDS(qa_out(f)) }
tt <- st_drop_geometry(tornado_tracks); d <- tornado_exposure; yr <- as.integer(substr(tt$tornado_id, 1, 4)); isna <- is.na(tt$property_loss_tornado_total); el <- yr <= 2006; m07 <- yr >= 2007
kl <- readLines("data-raw/known_issues.md")
put <- function(name, txt) { txt <- c(paste0("<!-- ", name, ":start -->"), txt, paste0("<!-- ", name, ":end -->")); a <- grep(paste0("<!-- ", name, ":start -->"), kl, fixed = TRUE); b <- grep(paste0("<!-- ", name, ":end -->"), kl, fixed = TRUE)
  if (!length(a) || !length(b)) stop("No marker for the block ", name, " in known_issues.md", call. = FALSE); kl <<- c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) }
wprov <- read.csv("data-raw/provenance_water.csv", stringsAsFactors = FALSE); prov <- read.csv("data-raw/provenance_years.csv", stringsAsFactors = FALSE); popr <- read.csv("data-raw/provenance_population.csv", stringsAsFactors = FALSE)

# ---- intro ---------------------------------------------------------------------------------------------------------------------------------------
put("intro", c("# Known issues in the source data and the model", "",
 paste0("Numbers below were computed by the scripts in `data-raw/qa/` from the data built from the SPC file `1950-", max(yr), "_all_tornadoes.csv` (accessed ", prov$access_date[nrow(prov)], ", md5 and size in `provenance.txt`) and the NWS Damage Assessment Toolkit data queried on ", readLines("data-raw/dat/access_date.txt"), ". They describe the current build; run the scripts again after a data change. No data are changed to work around any of these items."), "",
 "**Terms used on this page.**", "",
 "* *Exposed*: a ZCTA is exposed by the SPC when the SPC line (the straight line from SPC's start point to its end point) crosses it, that is, a positive length of the line lies in it; for a tornado with no usable end point, when the ZCTA contains the start point. It is exposed by the NWS survey when a damage polygon of a linked NWS line covers some land in it.",
 "* *Footprint*: the union of the damage polygons rated EF0 to EF5 that a linked DAT line touches (the polygon rule); it is cut into zones by the highest rating that covers each part.",
 "* *Land-only shape*: a unit polygon (ZCTA or block) minus the Census water polygons inside it.",
 "* *No usable end point*: SPC's end coordinates are missing, 0, or equal to the start. The tornado is a point at its start (`track_type = \"point\"`); its direction and extent are unknown.",
 "* *Chord*: the straight-line distance between a tornado's start and end points.",
 "* *Percentiles* (10th, 25th, 75th, 90th and 99th, with the median): they describe the spread of a distribution; none is a tested choice.",
 "* *Boundary year*: the Census Bureau ZCTA boundary file of the 2000, 2010 or 2020 census (the column of `zcta_centroids` is named `vintage`). Tornadoes of 1996-2009 use 2000, 2010-2019 use 2010, and 2020 on use 2020.",
 "* *DAT*: the National Weather Service Damage Assessment Toolkit; `dat_points`, `dat_lines` and `dat_polygons` are its features, as the service gives them."))

# ---- loss ----------------------------------------------------------------------------------------------------------------------------------------
spc <- d[d$spc_exposed, ]; tr_rows <- tapply(is.na(d$property_loss_tornado_total), d$tornado_id, function(x) x[1]); may <- tt[tt$tornado_id == "2021_2112102054-01", ]
nzr <- tt$loss_raw[tt$loss_raw > 0 & tt$loss_raw_unit == "millions"]; nzd <- tt$loss_raw[tt$loss_raw > 0 & tt$loss_raw_unit == "dollars"]
ym <- tapply(tt$loss_raw[tt$loss_raw > 0], yr[tt$loss_raw > 0], median); yM <- tapply(tt$loss_raw[tt$loss_raw > 0], yr[tt$loss_raw > 0], max)
noz <- !tt$tornado_id %in% spc$tornado_id
put("loss", c("## Property loss (SPC `loss`)", "",
 paste0("* SPC loss of 0 means unknown, not $0 (NOAA's wording), so `property_loss_tornado_total` and `property_loss_allocated` are `NA` for those tornadoes (the raw value 0 stays in `tornado_tracks$loss_raw`). ", f0(sum(isna)), " of ", f0(nrow(tt)), " tornadoes (", pc(mean(isna)), ") become `NA`: ", f0(sum(isna[el])), " of ", f0(sum(el)), " in 1996-2006 (", pc(mean(isna[el])), ") and ", f0(sum(isna[!el])), " of ", f0(sum(!el)), " from 2007 (", pc(mean(isna[!el])), "). In `tornado_exposure` that is ", f0(sum(is.na(d$property_loss_tornado_total))), " of ", f0(nrow(d)), " rows (", pc(mean(is.na(d$property_loss_tornado_total))), "; ", f0(sum(tr_rows)), " of the ", f0(length(tr_rows)), " tornadoes with rows). For tornadoes with a known loss and an SPC row the allocated values sum to the total; for the others, and for the rows that only the NWS polygons expose, they are `NA`."),
 paste0("* Loss is incomplete even for the deadliest tornadoes. Since 2007, ", f0(sum(isna & !is.na(tt$magnitude) & tt$magnitude >= 4 & m07)), " of ", f0(sum(!is.na(tt$magnitude) & tt$magnitude >= 4 & m07)), " EF4 and EF5 tornadoes have no loss recorded (`NA`), and ", f0(sum(isna & tt$total_fatality >= 10 & m07)), " of ", f0(sum(tt$total_fatality >= 10 & m07)), " tornadoes with at least 10 deaths (10 deaths is a cut-off chosen to show the deadliest tornadoes, not a tested choice). The Mayfield tornado `2021_2112102054-01` (", may$total_fatality, " deaths, ", may$total_injury, " injuries) has loss ", f0(may$property_loss_tornado_total), " dollars."),
 paste0("* Units: nonzero values are in millions of dollars through 2006 (yearly median at most ", sprintf("%.2f", max(ym[as.integer(names(ym)) <= 2006])), ", maximum ", f0(max(yM[as.integer(names(yM)) <= 2006])), ") and whole dollars from 2007 (yearly median at least ", f0(min(ym[as.integer(names(ym)) >= 2007])), "). The pipeline multiplies 1996-2006 by one million (an exact conversion; the build stops if a result is not a whole number of dollars up to floating-point error), keeps the raw value in `tornado_tracks$loss_raw` with `loss_raw_unit`, and stops if the break moves (limits in the table of constants below). SPC re-coded 2007-2015 from millions to dollars between its 2024 and 2025 releases, so it can change again."),
 paste0("* Loss of the ", f0(sum(noz)), " tornadoes with no SPC row is not allocated: ", f0(sum(tt$property_loss_tornado_total[noz], na.rm = TRUE)), " dollars (", f0(sum(noz & !isna)), " tornadoes with loss above 0), ", sprintf("%.3f", 100 * sum(tt$property_loss_tornado_total[noz], na.rm = TRUE) / sum(tt$property_loss_tornado_total, na.rm = TRUE)), "% of all loss."),
 paste0("* The allocation of a tornado's loss to its ZCTAs (`property_loss_allocated`) uses the share of the SPC line in each ZCTA, so it assumes that damage is spread evenly along the line and is an approximation (section SPC exposure). It is `NA` for the ", f0(sum(!d$spc_exposed)), " rows that only the NWS polygons expose.")))

# ---- coordinates -----------------------------------------------------------------------------------------------------------------------------------
r <- need("coordinate_rounding_summary.rds"); L <- tt$len_ratio; line <- tt$track_type == "line"
put("coordinates", c("## Coordinates", "",
 paste0("* SPC gives 1996-2006 coordinates to 0.01 degrees (about 1.1 km of latitude); from 2007 to 0.0001 degrees (about 11 m). The package does not round or move any coordinate. A simulation that moves each coordinate by up to half its rounding step (20 replicates, ", f0(r$tornadoes[1]), " tornadoes per era: sample sizes of this simulation, not tested choices; points keep the ZCTA that contains the start, lines use the ZCTAs the straight line crosses) changes the set of ZCTAs for ", sprintf("%.1f", r$`tornadoes_changed_%/rep`[1]), "% of 1996-2006 tornadoes per replicate (", sprintf("%.1f", r$`tornadoes_changed_in_any_rep_%`[1]), "% in at least one replicate) but ", sprintf("%.2f", r$`tornadoes_changed_%/rep`[2]), "% from 2007 (", sprintf("%.1f", r$`tornadoes_changed_in_any_rep_%`[2]), "% in at least one). A sensitivity analysis restricted to 2007 onward is recommended."),
 paste0("* From 2007 the reported length is close to the straight-line distance (`len_ratio` is above 1.5 for ", pc(mean(L[line & m07] > 1.5, na.rm = TRUE)), " of line tracks from 2007 against ", pc(mean(L[line & !m07] > 1.5, na.rm = TRUE)), " in 1996-2006), which suggests that it is computed from the coordinates, so `len_ratio` cannot independently validate modern coordinates.")))

# ---- SPC exposure ------------------------------------------------------------------------------------------------------------------------------------
nm <- read.csv("data-raw/readme/numbers.csv", stringsAsFactors = FALSE); N <- function(x) nm$value[match(x, nm$name)]; pa <- need("path_accuracy.rds")
tl <- readLines(qa_out("process_tracks.log")); touch_n <- sum(as.numeric(sub(".*: ([0-9]+)$", "\\1", grep("touch at a point only", tl, value = TRUE)))); ln <- tt$track_type == "line"; q5 <- quantile(tt$line_km[ln] / (as.numeric(st_length(st_transform(st_geometry(tornado_tracks)[ln], 5070))) / 1000), c(0, .01, .5, .99, 1), names = FALSE)
put("spc-line", c("## SPC exposure (`spc_exposed`, `line_km_in_zcta`, `line_share_of_tornado`, `property_loss_allocated`)", "",
 paste0("SPC records only a start point, an end point and one width for each tornado. The package draws only the straight line between the two points (straight in EPSG:5070) and builds no polygon from the width. Real tornado paths curve and their width varies along the track, and SPC's coordinates are rounded (section Coordinates). A ZCTA is exposed when a positive length of the line lies in it; a ZCTA that the line only touches at a point (zero length) is not exposed (", f0(touch_n), " line-ZCTA pairs in the build, counted in `out/process_tracks.log`). A tornado with no usable end point is a point at its start and exposes the ZCTA that contains the start point; a start point that lies in no ZCTA gives no SPC row."), "",
 paste0("**Line length and share.** `line_share_of_tornado` is the length of the line in the ZCTA divided by the length of the line in all the ZCTAs it reaches (both measured in EPSG:5070), so it sums to 1 over the SPC rows of a tornado; it is 1 for a point tornado. `line_km_in_zcta` is that share times `line_km`, the length of the whole line measured on the sphere (the measure that also gives `len_ratio`); for the ", f0(sum(ln)), " lines the 5070 length is between ", sprintf("%.4f", 1 / q5[5]), " and ", sprintf("%.4f", 1 / q5[1]), " times the spherical length (1st to 99th percentile ", sprintf("%.4f", 1 / q5[4]), " to ", sprintf("%.4f", 1 / q5[2]), "). `line_km_outside_zcta` (in `tornado_tracks`) is `line_km` minus the kilometers in ZCTAs: ", f0(sum(tt$line_km_outside_zcta > 1e-6, na.rm = TRUE)), " lines have more than 1e-6 km of their length in no ZCTA (water, areas that the Census assigns to no ZCTA; smaller values are floating-point residue, the largest is ", format(max(tt$line_km_outside_zcta[tt$line_km_outside_zcta <= 1e-6], na.rm = TRUE), digits = 2), " km)."), "",
 "**What SPC's width means.** NWS instructions for Storm Data define the path width entered for a tornado as the maximum width. NWSI 10-1605 ([current text, 26 July 2021](https://www.weather.gov/media/directives/010_pdfs/pd01016005curr.pdf)), section 47.7 \"Determining Path Length and Width\": \"Path length (in miles and tenths of miles) and maximum path width (in yards) will be indicated for all tornadoes, including each member of families of tornadoes, or for all segments of multi-segmented tornadoes.\" The archived text of 6 January 2003 ([archived appendix](https://www.weather.gov/media/directives/010_pdfs_archived/pd01016005a_incomplete.pdf)), section 31 \"Tornado (C)\": \"Path width in the entry header is the maximum width over the entire path, or of each segment in a multi-segment tornado.\" SPC compiles its database from Storm Data. SPC's current description ([SPC_severe_database_description.pdf](https://www.spc.noaa.gov/wcm/data/SPC_severe_database_description.pdf)) gives only \"Width in yards\". The package keeps `wid_yd` as given (a width of 0 is not replaced) and does not use it to draw anything.", "",
 paste0("**Comparison with the NWS damage polygons.** For the ", f0(N("spc_vs_dat_n")), " tornadoes with a linked DAT line and at least one linked EF0 to EF5 polygon (`data-raw/qa/66_spc_vs_dat.R`), the SPC line and the polygons expose the same ZCTA in ", f0(N("spc_vs_dat_both")), " tornado-ZCTA pairs, the line alone in ", f0(N("spc_vs_dat_spc_only")), " and the polygons alone in ", f0(N("spc_vs_dat_dat_only")), "; the two sets agree for ", sprintf("%.1f", N("spc_vs_dat_agreement_pct")), "% (pairs in both over pairs in either), ", sprintf("%.1f", N("spc_vs_dat_agreement_line_pct")), "% for line tornadoes and ", sprintf("%.1f", N("spc_vs_dat_agreement_point_pct")), "% for the ", f0(N("spc_vs_dat_point_n")), " tornadoes with no usable end point. Per tornado the median agreement is ", sprintf("%.1f", N("spc_vs_dat_per_tornado_median_pct")), "%; ", f0(N("spc_vs_dat_identical_n")), " tornadoes have identical sets and ", f0(N("spc_vs_dat_none_in_common_n")), " have no ZCTA in common. The ZCTAs exposed only by the polygons are ", sprintf("%.2f", N("spc_vs_dat_dat_only_dist_median_km")), " km (median), ", sprintf("%.2f", N("spc_vs_dat_dat_only_dist_p90_km")), " km (90th percentile) and ", sprintf("%.2f", N("spc_vs_dat_dat_only_dist_max_km")), " km (largest) from the SPC line. The accuracy of the NWS polygons has not been measured."), "",
 paste0("**Position.** For the ", f0(N("offset_n")), " SPC line tornadoes linked to a DAT line, the largest distance from a vertex of the DAT centerline to the SPC line has a median of ", sprintf("%.2f", N("offset_median_km")), " km and a 90th percentile of ", sprintf("%.2f", N("offset_p90_km")), " km (`data-raw/qa/46_path_accuracy.R`; every link counts, whatever its distance). By length of the SPC line: ", paste(vapply(seq_len(nrow(pa$by_class)), function(i) paste0(pa$by_class$cls[i], " (", f0(pa$by_class$n[i]), " links): median ", sprintf("%.2f", pa$by_class$median[i]), " km, 90th percentile ", sprintf("%.2f", pa$by_class$p90[i]), " km"), ""), collapse = "; "), ". A distance radius smaller than these values cannot separate exposure from path-location error.")))

# ---- identifiers --------------------------------------------------------------------------------------------------------------------------------------
x <- need("documented_39.rds")
put("identifiers", c("## Identifiers and SPC revisions", "",
 paste0("* `tornado_id` is unique within a package version only. SPC changed its `om` numbering for 2007 onward between its 2024 and 2025 releases (all ", f0(x$om_changed_2007), " matched 2007+ tornadoes changed ids). Distinct tornadoes that share a year and `om` in SPC (", paste(grep("^[0-9]{4}_[0-9]+(-[0-9]+)?_[0-9]+$", tt$tornado_id, value = TRUE), collapse = ", "), ") are suffixed `_1` and `_2`; `spc_records$tornado_id` carries the same ids."),
 paste0("* SPC revises records between releases. Comparing the 2024 and 2025 files for the whole-track records of EF1 and above from 1996 to 2024, matched by date and start latitude and longitude: ", f0(x$matched), " tornadoes matched; magnitude changed for ", x$mag, ", injuries for ", x$inj, ", fatalities for ", x$fat, ", `len` for ", x$len, " and `wid` for ", x$wid, "; loss changed for ", f0(x$loss), " (", f0(x$loss_changed_by_1e6), " of them by exactly a factor of one million, the unit re-coding of 2007 to 2015). ", x$early_any_change, " records of 1996-2006 changed in any of these values or in their id (`data-raw/qa/39_spc_release_comparison.R`). Stored years are frozen; an update appends only new years.")))

# ---- ratings ------------------------------------------------------------------------------------------------------------------------------------------
put("ratings", c("## Ratings", "",
 paste0("* All ratings are kept: ", f0(sum(tt$magnitude == 0, na.rm = TRUE)), " EF0, ", f0(sum(tt$magnitude >= 1, na.rm = TRUE)), " EF1-EF5 and ", f0(sum(is.na(tt$magnitude))), " unknown (SPC code -9, stored as `NA`). No other magnitude code occurs (the build stops on one). Ratings before 2007 are on the original Fujita scale.")))

# ---- dependence ------------------------------------------------------------------------------------------------------------------------------------
fl <- c(TABBLOCK20 = "tabblock20", TABBLOCK10 = "tabblock10", TABBLOCK00 = "tabblock00"); gb <- function(p) sum(popr$bytes[grepl(p, popr$url)]) / 1e9
put("dependence", c("## Dependence on upstream data", "",
 paste0("* The shipped data (`data/`) hold everything the functions need. Installing and using the package needs no upstream download, except that `map_exposure()` downloads boundaries from the Census Bureau (through tigris) when it runs and `get_data(boundary_dist_km = )` downloads the full TIGER/Line ZCTA file of the boundary year (the sizes are in the help pages)."),
 paste0("* A full rebuild reads the SPC tornado file (one URL, ", sprintf("%.1f", prov$bytes[nrow(prov)] / 1e6), " MB), the full TIGER/Line ZCTA files for 2000, 2010 and 2020 (through tigris), and, for population and land-only shapes, the Census TIGER/Line water polygons (", sprintf("%.1f", sum(wprov$bytes) / 1e9), " GB, ", nrow(wprov), " files, `data-raw/provenance_water.csv`) and the Census TIGER/Line tabulation blocks (2020: ", sprintf("%.1f", gb("tabblock20")), " GB; 2010: ", sprintf("%.1f", gb("tabblock10")), " GB; 2000: ", sprintf("%.1f", gb("tabblock00")), " GB) and the PL 94-171 files (", sprintf("%.1f", gb("census_2010")), " GB for 2010 and ", sprintf("%.1f", gb("census_2000")), " GB for 2000), ", sprintf("%.1f", sum(popr$bytes) / 1e9), " GB in all (", nrow(popr), " files, listed with size and md5 in `data-raw/provenance_population.csv`). The population downloads are cached outside the repository (see `pop_cache()` in `data-raw/population/population_functions.R`)."),
 "* A yearly update (`data-raw/update_data.R`) is much smaller than a rebuild: the SPC file and the ZCTA boundary file of the boundary year. The DAT data are fetched whole again (`data-raw/dat/fetch_dat.R`, then `data-raw/dat/build_dat.R` and `data-raw/dat/build_dat_exposure.R`, which reads the tabulation blocks of the states the DAT footprints touch and the water polygons): the service can change, so a rebuild can differ from the stored DAT datasets, and the link tables and DAT columns are rebuilt from the new fetch.",
 "* Raw downloads are not archived with the package or the repository, and are never committed. The md5 and size of each SPC download, with the years that came from it (`data-raw/provenance_years.csv`), the manifest of every population download and the software versions (`data-raw/provenance.txt`) let a rebuild check that it reads the same files; the DAT fetch is described by `data-raw/dat/fetch/fetch_summary.rds` (count the service reported, features read, size, time; git-ignored) and its date in `data-raw/dat/access_date.txt`.",
 "* Risk: a full rebuild depends on the Census Bureau, SPC and the DAT service keeping their URLs available and unchanged. If they move, disappear, or (for SPC and the DAT service) are revised, a rebuild will not reproduce the shipped data, although the shipped data stay valid. Yearly updates append only new years to the SPC tables and leave stored years frozen."))

# ---- settings ---------------------------------------------------------------------------------------------------------------------------------------
put("settings", c("## Constants of the package", "",
 "Every constant in the code that is not a source value, with its definition, value, reason and effect. None was tuned to make a result look better.", "",
 "| Constant (file) | Definition | Value | Reason | Effect |", "|---|---|---|---|---|",
 "| `first_year` (`data-raw/pipeline_functions.R`) | first year of the data | 1996 | inherited from the original package; no reason is documented | tornadoes before 1996 are not in the package |",
 "| loss break year, guard limits (`spc_clean()`) | the year SPC's loss changes from millions to dollars, and the yearly median and maximum limits that detect a moved break | 2007; median at most 1 and maximum at most 10,000 (millions) before; median at least 10,000 (dollars) from | the observed ranges (before 2007: median at most 0.07, maximum 1,000; from 2007: median at least 50,000) lie on both sides of the limits | the build stops if the break moves; no value changes |",
 "| exact-conversion tolerance (`spc_clean()`) | largest relative difference between the converted loss and a whole number of dollars | 1e-9 | floating-point error | the build stops if a value is not a whole number of dollars |",
 "| sanity limits of the update (`check_new_rows()`) | latitude, longitude, width, length, loss | latitude 15 to 72, longitude -180 to -60, width 0 to 10,000 yards, length 0 to 400 miles, known loss with a median of at least 10,000 and a maximum below 1e11 dollars | corrupt records fall outside; the extremes in the data lie well inside | the update stops and writes nothing; no value changes |",
 "| share tolerance (`block_pass()`, `build_dat_exposure.R`) | largest share of the land of a block, ZCTA or unit covered by the footprint above 1 that is treated as floating-point error | 1e-9 | the largest share found is 1 plus floating-point error | the build stops above it; a share is never capped |",
 "| polygon rule (`footprint_pairs()`) | a DAT polygon belongs to a tornado when a linked line touches it, and only polygons rated EF0 to EF5 are used | `line_share_in_polygon` above 0; efscale EF0 to EF5 | a zero test, not a cutoff; the other values of `efscale` are not damage ratings | which polygons make up a tornado's footprint (section DAT columns) |",
 "| damage-point window (`build_dat_exposure.R`) | a damage point counts for a tornado when its UTC date is within this many days of the tornado's date | 1 day | the same window as the link, for the same reason | the `dat_points_*` columns |",
 "| link window (`data-raw/dat/pairing_functions.R`) | DAT lines and SPC tornadoes are candidates when dated within this many days | 1 day | SPC uses local dates and the DAT date is the UTC date of `stormdate`, so the same event can be a day apart | a line is linked only to a tornado within a day |",
 "| link sample points (`n_samples`) | equally spaced points along each path for the index-aligned distance | 21 | a point every 5% of the length | defines `index_aligned_dist_km` and `one_sided_dist_km` |",
 "| distance index factor (`.distance_pairs()`) | oversize factor of the buffer used to pick candidate pairs before exact distances | 1.05 | the index uses a buffer in a projection | no pair within the radius is missed; exact distances decide |",
 "| display notes (`R/`) | a message is printed above these sizes | more than 2,000 damage points; a distance call estimated at 20 seconds or more | a note for large requests | no result changes |"))
writeLines(kl, "data-raw/known_issues.md"); cat("written\n")
